'use strict';
const $=q=>document.querySelector(q),G=Game,KEY='vestkyst-save-v1';
let s=G.fresh(),view='home',noticeTimer;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(G.valid(raw))s=G.upgrade(raw);}catch(e){}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kr=n=>Math.round(n).toLocaleString('nb-NO')+' kr',debit=n=>(Math.round(n)>0?'−':'')+kr(Math.max(0,n)),pct=n=>(n*100).toFixed(1).replace('.',',')+' %';
const btn=(act,arg,label,disabled=false,cls='button')=>`<button class="${cls}" data-act="${act}" data-arg="${arg}" ${disabled?'disabled':''}>${label}</button>`;
const meter=(n,cls='')=>`<div class="meter ${cls}"><i style="width:${Math.max(0,Math.min(100,n))}%"></i></div>`;
const nav=[['home','01','Kaien'],['routes','02','Rutene'],['cities','03','Byene'],['crew','04','Laget'],['rivals','05','Rivalene'],['legacy','06','Arven'],['ledger','07','Regnskap']];
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));}catch(e){toast('Lagringen mislyktes. Eksporter en sikkerhetskopi.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function act(type,arg){const msg=G.act(s,type,arg);save();render();toast(msg);return msg;}
function modal(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal();}
function portrait(i=0){const colors=['#d2a46e','#b9a276','#c17a58','#aeb17a','#779a9d','#a48ca8'],col=colors[i%6];return `<svg viewBox="0 0 100 115" aria-hidden="true"><defs><pattern id="rain${i}" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M9 0L6 7" stroke="#fff" stroke-opacity=".1"/></pattern></defs><rect width="100" height="115" fill="${col}"/><rect width="100" height="115" fill="url(#rain${i})"/><path d="M7 115Q5 81 33 77L38 65H64L70 79Q96 84 98 115" fill="#182023"/><path d="M34 41Q32 18 53 17Q77 19 69 49L66 65 53 77 39 65Z" fill="#c9b095"/><path d="M33 43L30 27Q36 11 58 13L74 26 69 45 61 33 36 37Z" fill="#20282a"/><path d="M41 50H46M57 50H63" stroke="#343334" stroke-width="3"/><path d="M48 63L59 62" stroke="#6c5a4b" stroke-width="2"/><path d="M33 79L45 100 53 78 64 100 72 79" stroke="#364246" fill="none" stroke-width="3"/></svg>`;}
function date(){return new Date(Math.min(Date.UTC(2026,0,1+s.week*7),Date.UTC(2036,11,31))).toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});}
function drawFixedCosts(){const q=G.fixedCosts(s,+$('#period').value);$('#fixedCosts').textContent=`Faste utgifter ved ${q.weeks} hele uker: ${kr(q.total)} (${kr(q.weekly)} / uke). Inntekter, varekjøp og engangskostnader kommer i tillegg. Perioden kan stoppe tidligere.`;}
function render(){
drawFixedCosts();
$('#nav').innerHTML=nav.map(([id,no,title])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span>${no}</span>${title}${id==='rivals'?'<b>NPC</b>':''}</button>`).join('');
$('#date').textContent=date();$('#policy').value=s.policy;$('#rank').textContent=G.rank(s)+' / '+s.rep+' respekt';$('#cash').textContent=kr(s.cash);$('#player').textContent=s.name;$('#heatValue').textContent=Math.round(s.heat)+'/100';$('#heatBar').innerHTML=meter(s.heat,s.heat>60?'danger':'');$('#loyalty').textContent=Math.round(s.crew.loyalty);$('#influence').textContent=s.influence;$('#advance').disabled=s.ended||!!s.event;
$('#event').innerHTML=eventPanel();$('#screen').innerHTML=({home,routes,cities,crew,rivals,legacy,ledger}[view])();
$('#period').disabled=s.ended;$('#statusline').textContent=s.ended?'2036 / RUNDEN ER AVSLUTTET':s.event?'MELDING VENTER / DIN AVGJØRELSE':!G.canDelegate(s)&&!s.routes.length?'DU HÅNDTERER VARER / BYGG OPP SALGSAPPARATET':s.auto?'LEDERNE TAR SMÅTINGENE / DU TAR DE STORE VALGENE':'ALLE MELDINGER SENDES TIL DEG';
}
function eventPanel(){if(!s.event)return '';const e=G.eventInfo(s);return `<section class="event-paper"><div class="section-kicker">INNKOMMEN / ${esc(e.speaker)}</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="event-choices">${e.choices.map((c,i)=>btn('choice',i,esc(c.name)+`<small>${c.cash>=0?'+':''}${kr(c.cash)} · ${c.influence>=0?'+':''}${c.influence||0} innflytelse · ${c.loyalty>=0?'+':''}${c.loyalty||0} lojalitet</small>`,s.cash+c.cash<0,'choice')).join('')}</div>${btn('defer','','Utsett · −1 lojalitet',false,'text-button')}</section>`;}
function summary(){return s.summary?`<div class="summary"><span>SIDEN SIST / ${s.summary.days!==undefined?s.summary.days+' DAGER':s.summary.weeks+' UKER'}</span><strong class="${s.summary.net>=0?'profit':'loss'}">${s.summary.net>=0?'+':''}${kr(s.summary.net)}</strong><p>${esc(s.summary.stop)} Beløpet er samlet endring i kassa, inkludert belønninger.</p><button class="text-button" data-view="ledger">Se oppgjørene ↗</button></div>`:'';}
function mission(){const i=s.chapters.length,c=G.STORY[i];return c?`<article class="dossier"><div class="tape"></div><div class="section-kicker">SAK ${String(i+1).padStart(2,'0')} / ${i<2?'STAVANGER':'NASJONALT'}</div><h2>${c.name}</h2><p>${c.text}</p><div class="reward">${kr(c.reward)} <span>+${c.influence} innflytelse</span></div>${meter(i/7*100)}<span class="mono-small">${i} AV 7 KAPITLER FULLFØRT · BELØNNING GÅR AUTOMATISK</span></article>`:`<article class="dossier"><div class="tape"></div><span class="stamp">ALLE SAKER LØST</span><h2>Ka står igjen?</h2><p>Historien er din. Byene, rivalene og kvartalsavtalene lever videre til slutten av 2036.</p></article>`;}
function home(){const owned=s.districts.length;return `${s.ended?endReport():''}<div class="home-layout"><section class="harbor"><div class="harbor-image"></div><div class="harbor-caption"><div class="section-kicker">58°58′N 5°44′E / VÅGEN · 2026—2036</div><h1>${G.rank(s)==='Gudfar'?'BYEN E DIN.<br>MEN KOR LENGE?':'ALLE VIL OPP.<br>FÅ BLIR IGJEN.'}</h1><p>Små gater. Lange minner.<br>Et helt tiår å sette spor i.</p><div class="scene-buttons"><button class="button brass" data-view="routes">${s.routes.length?'Se rutene dine':'Din første driftsavtale'} ↗</button><button class="button glass" data-view="rivals">Møt rivalene</button></div></div><div class="weather-tag">↙ 8°C / REGN. SELVFØLGELIG.</div></section><div class="home-side">${mission()}<article class="phone"><div class="phone-top"><span class="signal">▂▄▆</span> RAGGEN <span>kryptert linje</span></div><div class="phone-message">«${s.routes.length?'Folkå tar vaktene. Du må tenka større. Men ikkje glem kem som stille opp.':'Du kan ikkje stå på kaien resten av livet. Skaff ei fast avtale. Så kan me snakka om neste by.'}»</div><span class="mono-small">LEST / VÅGEN</span><button class="text-button" data-view="crew">Se til laget →</button></article></div></div>${summary()}<section class="street-strip"><div><span class="section-kicker">HJEMMEBANEN</span><h2>Gatene som kjenner deg.</h2><p>${owned} av 5 områder · ${s.businesses.length} lokaler · ${s.cities.length} byer</p></div><div class="street-signs">${G.DISTRICTS.map((d,i)=>`<button data-act="district" data-arg="${i}" class="street-sign ${s.districts.includes(i)?'owned':''}" ${s.districts.includes(i)||s.cash<d.cost?'disabled':''}><span>${s.districts.includes(i)?'● I NETTVERKET':kr(d.cost)}</span>${d.name}</button>`).join('')}</div></section><div class="lower-home"><article class="blackbox"><span class="section-kicker">SIST PÅ LINJA</span>${s.log.slice(0,4).map(t=>`<p class="log-line">↳ ${esc(t)}</p>`).join('')}</article><article class="blackbox"><span class="section-kicker">LEDERENS BESKJED</span><h3>Ei uke uten deg?</h3><p>Innkjøp og salg går av seg selv. Fire eller tretten uker passerer fram til ei viktig avgjørelse, høyt søkelys eller lite penger.</p>${btn('rest','','Ligg lavt ei uke',s.ended||!!s.event,'button ghost')}${btn('shift','','Ta et skift · +3 500 kr før drift',s.ended||!!s.event,'text-button')}<small>−18 søkelys før aktive ruter · −12 slitasje · 60 % lokalinntekt</small></article></div>`;}
function routes(){return `<div class="page-title"><div><span class="section-kicker">DRIFTSAVTALER / ${s.routes.length} AV ${1+s.managers*2} PLASSER</span><h1>RUTENE GÅR.<br>DU SETTER RETNINGEN.</h1><p>Faste innkjøp. Synlig etterspørsel. Ingen manuell påfylling.</p></div><button class="button brass" id="newRoute">+ Ny fast rute</button></div>${summary()}${s.routes.length?s.routes.map(r=>{const q=G.quote(s,r);return `<article class="route-ticket"><div class="route-identity"><span class="section-kicker">AVTALE ${String(r.id).padStart(2,'0')} / ${r.active?'AKTIV':'PAUSET'}</span><h2>${G.ORIGINS[r.origin||0].name} <span>↗</span> ${G.CITIES[r.city].name}</h2><div class="cargo-tag">${G.GOODS[r.good].name} / ${G.CARRIERS[r.carrier].name}</div><p>${esc(r.last||'Venter på oppgjør')}</p></div><div class="route-math"><div class="between"><span>Neste ukes etterspørsel</span><strong>${q.d} enheter</strong></div>${meter(q.q/q.d*100,q.discounted?'danger':'')}<p>${q.q} planlagt · ${q.full} til ${kr(q.p)} / stk.${q.discounted?' · <b class="loss">'+q.discounted+' til 60 % pris</b>':''}<br>${r.adapt?'Tilpasses automatisk til fullprisgrensen.':'Fast mengde. Overskudd selges med synlig rabatt.'}</p><div class="quote-mini"><span>Bruttosalg <b>${kr(q.gross)}</b></span><span>Innkjøp <b>${debit(q.supply)}</b></span><span>Frakt <b>${debit(q.freight)}</b></span><span>Netto ved levering <b>${kr(q.net)}</b></span></div></div><div class="route-net"><span class="section-kicker">FORVENTET NETTO NESTE UKE</span><strong class="${q.expected>=0?'profit':'loss'}">${kr(q.expected)}</strong><p>Inkluderer ${pct(q.risk)} tapsrisiko.<br>${q.refund?'75 % av innkjøpet erstattes ved tap.':'Ved tap betaler du innkjøp og frakt.'}</p><div><button class="button ghost" data-edit-route="${r.id}">Endre</button>${btn('routeToggle',r.id,r.active?'Pause':'Start',false,'button ghost')}${btn('routeDelete',r.id,'Avslutt',false,'text-button')}</div></div></article>`;}).join(''):`<section class="empty-state"><span class="empty-icon">⇄</span><h2>Slutt å flytte hver kasse selv.</h2><p>Velg by, vare og ukentlig mengde én gang. Leverandør og driftskontakt håndterer resten.</p><button class="button brass" id="newRouteEmpty">Opprett din første rute</button></section>`}<div class="rule-note"><b>Ingen skjulte grenser.</b> Etterspørselen gjelder per by og vare hver uke. Én rute per vare/by hindrer dobbelbooking. «Tilpass automatisk» holder mengden innenfor fullprisgrensen. Forventet netto er et risikovektet snitt, ikke en lovet utbetaling.</div><section class="blackbox"><div class="between"><h2>Lederne tar småtingene.</h2>${btn('autonomy','',s.auto?'Delegert ✓':'Deleger småhendelser',false,'button ghost')}</div><p>Store byvalg og årshendelser stopper alltid tiden. Småhendelser kan lederne håndtere uten at du klikker deg gjennom dem.</p></section>`;}
function planner(existing=null){modal(`<span class="section-kicker">${existing?'ENDRE DRIFTSAVTALE':'NY DRIFTSAVTALE'}</span><h2>Ei rute. Ikke hundre klikk.</h2><form id="routeForm"><div class="form-grid"><label>Leverandør<select id="routeOrigin">${G.ORIGINS.map((o,i)=>`<option value="${i}" ${s.rankLevel<o.level?'disabled':''}>${o.name} / ${o.place}</option>`).join('')}</select></label><label>Salgsmarked<select id="routeCity">${s.cities.map(i=>`<option value="${i}">${G.CITIES[i].name}</option>`).join('')}</select></label><label>Vare<select id="routeGood">${G.GOODS.map((g,i)=>`<option value="${i}" ${!G.unlocked(s,i)?'disabled':''}>${g.name}${!G.unlocked(s,i)?' · låst av rang':''}</option>`).join('')}</select></label><label>Ukentlig mengde<input id="routeQty" type="number" min="1" max="6000" value="20" required></label><label>Transport<select id="routeCarrier">${G.CARRIERS.map((c,i)=>`<option value="${i}">${c.name} · grunnkapasitet ${c.cap}</option>`).join('')}</select></label></div><label class="check-label"><input id="routeAdapt" type="checkbox" checked> Tilpass automatisk til etterspørselen</label><div id="routeQuote"></div><button class="button brass" type="submit">${existing?'Lagre ruten':'Start fast rute ↗'}</button></form>`);if(existing){$('#routeOrigin').value=existing.origin||0;$('#routeCity').value=existing.city;$('#routeGood').value=existing.good;$('#routeQty').value=existing.qty;$('#routeCarrier').value=existing.carrier;$('#routeAdapt').checked=existing.adapt;}const fields=['routeOrigin','routeCity','routeGood','routeQty','routeCarrier','routeAdapt'];const read=()=>({id:existing?.id,origin:+$('#routeOrigin').value,city:+$('#routeCity').value,good:+$('#routeGood').value,qty:+$('#routeQty').value,carrier:+$('#routeCarrier').value,adapt:$('#routeAdapt').checked});function draw(){const origin=+$('#routeOrigin').value;for(const opt of $('#routeGood').options)opt.disabled=!G.ORIGINS[origin].goods[+opt.value]||!G.unlocked(s,+opt.value);if($('#routeGood').selectedOptions[0]?.disabled){const available=[...$('#routeGood').options].find(o=>!o.disabled);if(available)$('#routeGood').value=available.value;}const r=read();if(!Number.isInteger(r.qty)||r.qty<1){$('#routeQuote').textContent='Velg en positiv, hel mengde.';return;}const q=G.quote(s,r);$('#routeQty').max=G.routeCapacity(s,r);$('#routeQuote').innerHTML=`<div class="planner-quote"><div class="between"><span>Fullprisgrense neste uke</span><b>${q.d} / uke</b></div><div class="between"><span>Planlagt mengde</span><b>${q.q} · ${q.discounted} til rabatt</b></div><div class="between"><span>Bruttosalg</span><b>${kr(q.gross)}</b></div><div class="between"><span>Innkjøp + frakt</span><b>−${kr(q.supply+q.freight)}</b></div><div class="between"><span>Netto ved levering</span><b>${kr(q.net)}</b></div><div class="between"><span>Risiko / innkjøp erstattet</span><b>${pct(q.risk)} / ${pct(q.refund)}</b></div><div class="between estimate"><span>Forventet netto neste uke</span><b class="${q.expected>=0?'profit':'loss'}">${kr(q.expected)}</b></div><p class="small">Du trenger ${kr(q.supply+q.freight)} i driftskapital. Ruten pauser oppgjøret hvis kassa ikke dekker innkjøpet.${q.expected<0?' Denne avtalen har negativ forventet netto.':''}</p></div>`;}fields.forEach(id=>$('#'+id).addEventListener('input',draw));draw();$('#routeForm').onsubmit=e=>{e.preventDefault();const result=act(existing?'routeEdit':'routeAdd',{...read(),...(existing?{id:existing.id}:{})});if(result.startsWith('Fast rute opprettet')||result==='Ruten er oppdatert.')$('#dialog').close();};}
function cities(){const roles=['Hjemmebanen','Handel og allianser','Sesonger og kontakter','Folk og logistikk','Makt og rivalisering'];return `<div class="page-title"><div><span class="section-kicker">EKSPANSJON / ${s.cities.length} AV 5 BYER</span><h1>EN NY BY.<br>ET ANNET SPILL.</h1><p>En etablering er starten. Tre lokale kapitler former hvem som styrer, hva byen gjør og hvem som får en andel.</p></div><span class="rubber-stamp">FRA KAIEN<br>TIL HELE KARTET</span></div><div class="city-list">${G.CITIES.map((c,i)=>{const b=s.branches[i],owned=s.cities.includes(i);return `<article class="city-file ${owned?'established':''}"><div class="city-number">0${i+1}</div><div class="city-description"><span class="section-kicker">${roles[i]}</span><h2>${c.name}</h2><p>${i?G.LORDS[i].line:'«Det begynne på kaien.»'}</p>${owned?`<div class="city-state"><span>Nivå ${b.level} / 3</span><span>${({balanced:'Ingen spesialitet',trade:'Handelsmotor',influence:'Innflytelse',logistics:'Logistikk'})[b.focus]}</span><span>${b.approach==='alliance'?'Delt eierskap':'Egen regi'}</span></div>${meter(b.level/3*100)}<p class="small">Rivalpress ${Math.round(b.pressure)}/100 · senker byinntekten. Allianser og innflytelse demper presset.</p>`:`<p class="requirements">${kr(c.cost)} · ${c.rep} respekt · ${i*5} innflytelse · ${s.cities.length} ledere totalt</p>`}</div><div class="city-action">${owned?`<span class="stamp">ETABLERT</span>${i?'<p class="small">Neste lokale kapittel etter '+([4,17,35][b.level]||'—')+' uker fra etablering.</p>':''}`:btn('city',i,'Etabler utpost ↗',s.cash<c.cost||s.rep<c.rep||s.influence<i*5||s.managers<s.cities.length,'button brass')}</div></article>`;}).join('')}</div><h2 class="section-heading">Lokaler i Stavanger</h2><div class="business-grid">${G.BUSINESSES.map((b,i)=>`<article class="business"><span class="section-kicker">${b.place} / LOKAL VIRKSOMHET</span><h3>${b.name}</h3><p>+${kr(b.income)} brutto / uke</p>${s.businesses.includes(i)?'<span class="stamp">DIN</span>':btn('business',i,'Kjøp · '+kr(b.cost),s.cash<b.cost,'button ghost')}</article>`).join('')}</div>`;}
function crew(){const recruit=G.recruitQuote(s),training=G.trainingQuote(s);return `<div class="page-title"><div><span class="section-kicker">LAGET / ${s.managers} DRIFTSLEDERE</span><h1>FOLK KAN MISTES.<br>RESPEKT MÅ FORTJENES.</h1><p>Styrke følger antall, trening, lojalitet og slitasje. Ingen permanent «95 % og ferdig».</p></div><div class="crew-portrait">${portrait(0)}</div></div><div class="crew-board"><div class="crew-numbers"><div><strong>${s.crew.members}</strong><span>FOLK PÅ LAGET</span></div><div><strong>${s.crew.trained}</strong><span>MED TRENING</span></div><div><strong>${G.power(s)}</strong><span>STYRKE NÅ</span></div></div><div class="crew-condition"><label>Lojalitet <b>${Math.round(s.crew.loyalty)} / 100</b></label>${meter(s.crew.loyalty)}<label>Slitasje <b>${Math.round(s.crew.fatigue)} / 100</b></label>${meter(s.crew.fatigue,'danger')}<p>Lav lojalitet svekker styrken og øker risiko på rutene. Slitasje reduserer kampkraften; hvile bygger den opp igjen.</p></div></div><div class="crew-actions"><article class="blackbox"><span class="section-kicker">REKRUTTERING</span><h2>Nye ansikter.</h2><p>${recruit.n} nye folk. −2 lojalitet mens de finner sin plass. Ett opptak per uke.</p>${btn('recruit','','Rekrutter '+recruit.n+' · '+kr(recruit.cost),s.cash<recruit.cost||s.lastRecruit===s.week,'button brass')}</article><article class="blackbox"><span class="section-kicker">TRENING</span><h2>Det må sitte i kroppen.</h2><p>Tren inntil ${training.n} folk for ${kr(training.cost)} etter lokale avtaler. +6 slitasje. Én økt per uke.</p>${btn('train','','Tren laget',s.crew.trained>=s.crew.members||s.lastTrain===s.week,'button ghost')}</article><article class="blackbox"><span class="section-kicker">LOJALITET</span><h2>Se dem som stiller opp.</h2><p>Bonus og pusterom: +12 lojalitet, −15 slitasje. Én gang per uke.</p>${btn('crewCare','','Ta vare på laget · '+kr(1000+s.crew.members*350),s.cash<1000+s.crew.members*350||s.lastCare===s.week,'button ghost')}</article></div><article class="leader-file"><div>${portrait(1)}</div><section><span class="section-kicker">DRIFTSLEDERE / ${s.managers} PÅ JOBB</span><h2>Du trenger ikkje stå hver vakt.</h2><p>Hver leder gir to ekstra ruteplasser og kan lede en ny utpost. Lønn 750 kr / uke. Lagets øvrige lønn inngår i driftskostnaden.</p>${btn('manager','','Ansett · '+kr(15000*(s.managers+1)),s.cash<15000*(s.managers+1),'button brass')}</section></article><p class="rule-note">Samlet fast drift nå: <b>${kr(G.upkeep(s))} / uke</b>. Inkluderer folk, treningstillegg, ledere og 500 kr faste utgifter. Manglende lønn reduserer lojaliteten.</p>`;}
function rivals(){return `<div class="page-title"><div><span class="section-kicker">FIKTIVE LORDS / SIMULERTE RIVALER</span><h1>DU E IKKJE DEN<br>ENESTE MED AMBISJONER.</h1><p>Undersøk. Forhandle. Ta et oppgjør. Alle rivaler er datastyrte; det finnes ingen andre spillere her.</p></div><div class="warning-label">KAMP KOSTER FOLK<br>OGSÅ NÅR DU VINNER</div></div>${s.battle?`<section class="battle-report"><span class="section-kicker">SISTE OPPGJØR / UKE ${s.battle.week+1}</span><h2>${s.battle.won?'Du vant territoriet.':'Rivalen holdt stand.'}</h2><p>${s.battle.losses} folk er ute av laget. Trente folk kan også gå tapt. Lojalitet og slitasje er oppdatert.</p></section>`:''}<div class="rival-grid">${G.LORDS.map((l,i)=>{const e=s.lords[i],locked=s.rep<G.CITIES[l.city].rep,known=s.week-e.scouted<=4;return `<article class="rival-card"><div class="rival-photo">${portrait(i+1)}<span class="rival-id">LORD / 0${i+1}</span></div><div class="rival-body"><span class="section-kicker">${i?G.CITIES[l.city].name:'Sandnes / Stavanger'}</span><h2>${l.name}</h2><p>${l.line}</p><div class="rival-facts"><span>Styrke <b>${known?G.enemy(s,i):'UKJENT'}</b></span><span>Din styrke <b>${G.power(s)}</b></span><span>Seierssjanse <b>${known?pct(G.odds(s,i)):'Undersøk først'}</b></span></div><p class="small">${e.wins} seire · ${e.deals?'Alliert':'Ingen allianse'} · Territoriegevinst ${kr(l.prize)}. Rivalene vokser gjennom tiåret.</p><div class="rival-buttons">${btn('scout',i,'Undersøk · 2 500 kr',locked||s.cash<2500,'button ghost')}<button class="button danger-button" data-fight="${i}" ${locked||s.crew.members<3||s.crew.fatigue>70||s.week-e.last<8||e.deals?'disabled':''}>Ta oppgjøret</button>${btn('deal',i,e.deals?'Alliert ✓':'Forhandle · '+kr(l.prize*2),locked||e.deals||s.cash<l.prize*2,'text-button')}</div></div></article>`;}).join('')}</div><div class="rule-note">En seier gir kapital, respekt og innflytelse, men alle kamper koster minst ett medlem. Nederlag gir større tap. Ingen ny kamp mot samme rival før åtte uker har gått. En allianse senker lokalt rivalpress og lar deg løse kapitler uten kamp.</div>`;}
function fight(i){const l=G.LORDS[i],known=s.week-s.lords[i].scouted<=4;modal(`<span class="section-kicker">BEKREFT OPPGJØR / ${l.name}</span><h2>Ka e du villig til å miste?</h2><p>Din styrke: <b>${G.power(s)}</b>. Rivalens styrke: <b>${known?G.enemy(s,i):'ukjent'}</b>. ${known?'Seierssjanse: '+pct(G.odds(s,i))+'.':''}</p><p>Kampen koster minst ett medlem, også ved seier. Du kan miste trente folk. +25 slitasje, +12 søkelys og −3 lojalitet ved seier eller −9 ved nederlag.</p><p>Ved seier: ${kr(l.prize)}, respekt og innflytelse. Ved nederlag: større tap og ingen gevinst.</p><button class="button danger-button" id="confirmFight">Gjennomfør oppgjøret</button><button class="button ghost" id="cancelFight">Trekk deg</button>`);$('#confirmFight').onclick=()=>{$('#dialog').close();act('battle',i);};$('#cancelFight').onclick=()=>$('#dialog').close();}
const goals={coast:['Vestkystkongen','Tre Stavanger-områder, en ferdigutviklet Bergen-utpost med rivalpress under 60 og minst 60 lojalitet.'],country:['Hele kartet','Alle fem byer. Fire ferdigutviklede utposter med rivalpress under 60, og minst 100 innflytelse.'],exit:['Den stille exiten','Minst 12 millioner i kassa, høyst 25 søkelys og åtte fullførte kvartalsavtaler.']};
function legacy(){const o=G.outcome(s),n=s.cities.length;return `<div class="page-title"><div><span class="section-kicker">2036 / MAKT ER MER ENN PENGER</span><h1>KA SKAL<br>STÅ IGJEN?</h1><p>Rang er begynnelsen. Stabilitet, folk, allianser og etterfølgelse avgjør arven.</p></div><span class="rubber-stamp">${574-s.week} UKER<br>Å SETTE SPOR</span></div><div class="legacy-grid">${Object.entries(goals).map(([id,[name,text]])=>`<article class="legacy-option ${s.goal===id?'chosen':''}"><span class="section-kicker">${s.goal===id?'DIN RETNING':'MULIG ARV'} / ${o[id]?'KRAV OPPFYLT':'UNDER OPPBYGGING'}</span><h2>${name}</h2><p>${text}</p>${btn('goal',id,s.goal===id?'Valgt ✓':'Velg denne arven',s.goal===id,'button ghost')}</article>`).join('')}</div><section class="contract-file"><span class="section-kicker">KVARTALSAVTALER / ${s.completed} FULLFØRT</span><h2>Bygg noe som varer lenger enn ei sending.</h2>${s.contract?`<p>Avtale i gang. ${s.contract.due-s.week} uker til oppgjør. Løpende drift ${kr(s.contract.weekly)} / uke. Brutto ${kr(s.contract.gross)} før trekk.</p>${meter((13-(s.contract.due-s.week))/13*100)}`:`<p>En 13-ukers avtale på tvers av ${n} ${n===1?'by':'byer'}. Innskudd ${kr(n*25000)}. Drift ${kr(n*1500)} per uke. Brutto oppgjør ${kr(n*100000)}.</p>${btn('contract','','Start kvartalsavtale',s.cash<n*25000||s.influence<5,'button brass')}`}<p class="small">Oppgjøret trekkes 0–40 % basert på søkelys og gjennomsnittlig rivalpress. Ubetalt avtaledrift trekkes også fra. Innskuddet er en kostnad og betales ikke tilbake i tillegg. Maks netto før risikotrekk: ${kr(s.contract?s.contract.gross-s.contract.deposit-s.contract.weekly*13:n*(100000-25000-1500*13))}. Avtalen krever 5 innflytelse og bruker 2.</p></section><section class="chapter-list"><h2>Historien fortsetter etter Gudfar.</h2>${G.STORY.map((c,i)=>`<div class="chapter-row ${s.chapters.includes(i)?'done':''}"><b>${s.chapters.includes(i)?'✓':String(i+1).padStart(2,'0')}</b><section><h3>${c.name}</h3><p>${c.text}</p></section><span>${kr(c.reward)}</span></div>`).join('')}</section>`;}
function ledger(){const rows=s.ledger.slice(0,60),net=rows.reduce((a,r)=>a+r.net,0);return `<div class="page-title"><div><span class="section-kicker">OPPGJØR / FAKTISKE BEVEGELSER</span><h1>INGENTING<br>FORSVINNER I TÅKA.</h1><p>Bruttosalg, innkjøp, frakt, refusjon og netto vises hver for seg. Ingen estimater føres som inntekt.</p></div><div class="ledger-total"><span>SISTE ${rows.length} POSTER</span><strong class="${net>=0?'profit':'loss'}">${kr(net)}</strong></div></div>${rows.length?`<div class="ledger-scroll"><table><thead><tr><th>UKE / OPPGJØR</th><th>BRUTTO</th><th>INNKJØP</th><th>FRAKT / DRIFT</th><th>REFUSJON</th><th>NETTO</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.week+1} / ${esc(r.title)}</b><small>${esc(r.status)}${r.q?' · '+r.q+' enheter · fullprisgrense '+r.demand:''}</small></td><td>${kr(r.gross||0)}</td><td>${r.supply?'−'+kr(r.supply):'—'}</td><td>${r.freight||r.cost?'−'+kr((r.freight||0)+(r.cost||0)):'—'}</td><td>${r.refund?'+'+kr(r.refund):'—'}</td><td class="${r.net>=0?'profit':'loss'}">${r.net>=0?'+':''}${kr(r.net)}${r.profit!==undefined?`<small>Varefortjeneste ${kr(r.profit)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><h2>Første oppgjør kommer når uka går.</h2><p>Opprett ei rute eller et fotfeste. Her ser du hva det faktisk ga.</p></div>`}<p class="rule-note">Viser inntil 60 av de siste 120 driftspostene. Kjøp av eiendom, rekruttering, kapittelbelønninger og strategiske engangsvalg vises i hendelsesloggen; de inngår i endringen i kassa.</p>`;}
function endReport(){const o=G.outcome(s);return `<section class="event-paper"><span class="section-kicker">31. DESEMBER 2036</span><h2>${o.won?'Du satte spor.':'Byen ble større enn planen.'}</h2><p>${goals[s.goal][0]}: ${o.won?'Målet er nådd.':'Målet ble ikke nådd.'} ${s.cities.length} byer, ${s.influence} innflytelse, ${s.crew.members} folk og ${kr(s.cash)}.</p></section>`;}
function settings(){modal(`<span class="section-kicker">DIN HISTORIE / LAGRES PÅ DENNE ENHETEN</span><h2>Et navn som blir igjen.</h2><label>Gatenavn<input id="playerName" maxlength="28" value="${esc(s.name)}"></label><button class="button brass" id="saveName">Lagre navn</button><hr><p>Spillet lagres automatisk i denne nettleseren. Ta en kopi for å fortsette på en annen enhet.</p><button class="button ghost" id="exportSave">Eksporter lagring</button><label class="button ghost file-label">Importer lagring<input type="file" id="importSave" accept="application/json" hidden></label><p class="small">Import erstatter runden her. Eksporter først hvis du vil beholde den.</p><button class="text-button" id="newGame">Start en ny runde…</button>`);}
$('#period').addEventListener('change',drawFixedCosts);
$('#advance').onclick=()=>act('advance',+$('#period').value);$('#settings').onclick=settings;$('#guide').onclick=()=>modal(`<span class="section-kicker">DET BEGYNNE PÅ KAIEN</span><h2>Du setter retningen.</h2><p><b>Start:</b> Kjøp fotfeste på Storhaug og opprett ei lita rute. 20 enheter sprit er et overkommelig første parti.</p><p><b>Drift:</b> Ruter kjøper og selger automatisk hver uke. Tilpass mengden til etterspørselen. Forventet netto inkluderer tapsrisiko; faktiske oppgjør vises i regnskapet.</p><p><b>Laget:</b> Rekrutter, tren og hold lojaliteten oppe. Kamper mot rivaler koster folk og slitasje. Forhandling er en egen vei til innflytelse.</p><p><b>Ekspansjon:</b> En ny by trenger kapital, respekt, innflytelse og en leder. Tre lokale kapitler bestemmer byens rolle og eierskap.</p><p><b>Tid:</b> La 1, 4 eller 13 uker gå. Viktige valg, høyt søkelys og lite kapital stopper perioden. «Ligg lavt» gir −18 søkelys før aktive ruter, −12 slitasje og 60 % lokalinntekt.</p><p><b>2036:</b> Velg arven din. Det holder ikke å kjøpe alt. Stabilitet og folk teller.</p><p class="small">Personer, virksomheter, kriminalhistorier og fremtidige hendelser er fiksjon. Rivalene er NPC-er, ikke virkelige spillere. Spillbalansen er fortsatt under utvikling.</p>`);
$('#closeDialog').onclick=()=>$('#dialog').close();
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});}if(b.dataset.act)act(b.dataset.act,b.dataset.arg);if(b.id==='newRoute'||b.id==='newRouteEmpty')planner();if(b.dataset.editRoute)planner(s.routes.find(r=>r.id===+b.dataset.editRoute));if(b.dataset.fight)fight(+b.dataset.fight);if(b.id==='saveName'){s.name=$('#playerName').value.trim().slice(0,28)||'Skipperen';save();render();toast('Navnet er lagret.');}if(b.id==='exportSave'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.download='vestkyst-uke-'+s.week+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}if(b.id==='newGame')modal(`<h2>En ny start på kaien?</h2><p>Eksporter lagringen først hvis du vil beholde denne runden. En ny runde erstatter den på enheten.</p><button class="button danger-button" id="confirmNew">Ja, start på nytt</button><button class="button ghost" id="cancelNew">Behold runden</button>`);if(b.id==='cancelNew')$('#dialog').close();if(b.id==='confirmNew'){s=G.fresh();view='home';save();render();$('#dialog').close();}});
document.addEventListener('change',async e=>{if(e.target.id==='importSave'){try{const raw=JSON.parse(await e.target.files[0].text());if(!G.valid(raw))throw Error();s=G.upgrade(raw);save();render();$('#dialog').close();toast('Runden er importert.');}catch(err){toast('Lagringen kunne ikke leses. Velg en gyldig Vestkyst-fil.');}}if(e.target.id==='policy'){act('policy',e.target.value);}});
render();
